// Combine all source documents into a single context block
const topic = $('Load Next Ingested Topic').first().json;
const sources = $('Load Source Documents').all().map(i => i.json);

const sourceBlock = sources.map(s => {
  const meta = typeof s.metadata === 'string' ? JSON.parse(s.metadata) : s.metadata;
  return `--- ${s.source_type.toUpperCase()}: ${s.title || 'Untitled'} ---\n${s.content_text.substring(0, 8000)}`;
}).join('\n\n');

const docIds = sources.map(s => s.id);

return [{ json: { topic, sourceBlock, docIds, sourceCount: sources.length } }];

